def find_solutions(max_c):
    solutions = []
    for c in range(1, max_c + 1):
        target = 6**c - 1
        for a in range(1, int(c * 2.585) + 2):
            rem = target - 2**a
            if rem > 0:
                # check if rem is a power of 3
                # 3^b = rem
                b = 0
                temp_rem = rem
                while temp_rem > 1 and temp_rem % 3 == 0:
                    temp_rem //= 3
                    b += 1
                if temp_rem == 1 and b > 0:
                    solutions.append((a, b, c))
    return solutions

solutions = find_solutions(20)
print(f"Solutions (a, b, c): {solutions}")

def solve():
    solutions = []
    for c in range(1, 15):
        S_val = 6**c
        for b in range(1, 15):
            T_val = 3**b
            two_pow_a = S_val - T_val - 1
            if two_pow_a > 0:
                if (two_pow_a & (two_pow_a - 1)) == 0:
                    a = two_pow_a.bit_length() - 1
                    if a > 0:
                        solutions.append((a, b, c))
    return solutions

solutions = solve()
print(f"Solutions (a, b, c): {solutions}")
